import type { LumiClient } from '@/core/lumi-client'

export enum StorageKey {
  ACCESS_TOKEN = 'lumi-access-token',
  USER = 'lumi-user',
}

export function setStorage<T>(lumi: LumiClient, key: StorageKey, value: T): void {
  const storage = lumi.config.storageAdapter.storage
  if (value !== null)
    storage.setItem(key, JSON.stringify(value))
  else
    storage.removeItem(key)
}

export function getStorage<T>(lumi: LumiClient, key: StorageKey): T | null {
  const storage = lumi.config.storageAdapter.storage
  const value = storage.getItem(key)
  try {
    return value ? JSON.parse(value) : null
  }
  catch {
    return null
  }
}
