import type { LumiClient } from '@/core/lumi-client'
import type { ApiResponse, User, UserWithToken } from '@/types'
import SHA256 from 'crypto-js/sha256'
import { v4 } from 'uuid'
import { LumiError } from '@/lib/error'
import { request } from '@/lib/request'
import { getIcon, getTitle, isServer } from '@/utils/common'
import { getStorage, setStorage, StorageKey } from '@/utils/storage'

type OAuthProvider = 'google'
type OtpType = 'register' | 'resetPassword'

enum ReceiveMessageType {
  READY = 'lumi-ready',
  SIGN_IN = 'lumi-sign-in',
  SIGN_IN_FAILED = 'lumi-sign-in-failed',
}

enum SendMessageType {
  INIT = 'lumi-init',
}

interface MessageSignInData {
  projectId: string
  accessToken: string
  user: User
}

type MessageDataReceive = {
  type: ReceiveMessageType.READY | ReceiveMessageType.SIGN_IN_FAILED
} | {
  type: ReceiveMessageType.SIGN_IN
  data: MessageSignInData
}

interface MessageInitData {
  projectId: string
  icon: string | null
  title: string | null
}

interface MessageDataSend {
  type: SendMessageType.INIT
  data: MessageInitData
}

export class LumiAuthClient {
  readonly #lumi: LumiClient
  readonly #popupName: string = `lumi-auth-${v4()}`

  constructor(lumi: LumiClient) {
    this.#lumi = lumi
    Promise.resolve().then(() => {
      if (!isServer && this.isAuthenticated)
        void this.refreshUser()
    })
  }

  /** 访问令牌 */
  public get accessToken(): string | null {
    if (isServer) {
      const authorization = this.#lumi.config.authorization
      return authorization ? authorization.replace('Bearer ', '') : null
    }
    return getStorage<string>(this.#lumi, StorageKey.ACCESS_TOKEN)
  }

  public set accessToken(accessToken: string | null) {
    if (isServer) {
      this.#lumi.config.authorization = accessToken ? `Bearer ${accessToken}` : undefined
      return
    }
    setStorage(this.#lumi, StorageKey.ACCESS_TOKEN, accessToken)
  }

  #user: User | null = null

  /** 用户 */
  public get user(): User | null {
    if (isServer)
      return this.#user
    return getStorage<User>(this.#lumi, StorageKey.USER)
  }

  public set user(user: User | null) {
    if (isServer) {
      this.#user = user
      return
    }
    setStorage(this.#lumi, StorageKey.USER, user)
  }

  public get isAuthenticated(): boolean {
    return !!this.accessToken
  }

  /** 登录 */
  public signIn(): Promise<MessageSignInData> {
    return this.#openAuthPopup(this.#lumi.config.authOrigin)
  }

  /** 使用密码登录 */
  public async signInWithPassword({
    email,
    password,
  }: {
    email: string
    password: string
  }): Promise<MessageSignInData> {
    const res = await request<ApiResponse<UserWithToken>>(this.#lumi, '/lm/user/password/login', {
      method: 'POST',
      body: {
        projectId: this.#lumi.config.projectId,
        email,
        password: SHA256(password).toString(),
      },
    })

    if (res.code !== 200)
      throw new LumiError(res.code, res.message)

    this.accessToken = res.data.userToken
    this.user = res.data

    return {
      projectId: this.#lumi.config.projectId,
      accessToken: res.data.userToken,
      user: res.data,
    }
  }

  /** 发送验证码 */
  public async sendOtp({
    email,
    type,
  }: {
    email: string
    type: OtpType
  }): Promise<void> {
    const res = await request<ApiResponse<null>>(this.#lumi, '/lm/user/email/code/send', {
      method: 'POST',
      body: {
        projectId: this.#lumi.config.projectId,
        email,
        emailType: type,
      },
    })
    if (res.code !== 200)
      throw new LumiError(res.code, res.message)
  }

  /** 使用密码注册 */
  public async signUpWithPassword({
    email,
    password,
    otp,
    userName,
  }: {
    email: string
    password: string
    otp: string
    userName?: string
  }): Promise<MessageSignInData> {
    const res = await request<ApiResponse<UserWithToken>>(this.#lumi, '/lm/user/password/register', {
      method: 'POST',
      body: {
        projectId: this.#lumi.config.projectId,
        email,
        password: SHA256(password).toString(),
        code: otp,
        userName,
      },
    })

    if (res.code !== 200)
      throw new LumiError(res.code, res.message)

    this.accessToken = res.data.userToken
    this.user = res.data

    return {
      projectId: this.#lumi.config.projectId,
      accessToken: res.data.userToken,
      user: res.data,
    }
  }

  /** 重置密码 */
  public async resetPassword({
    email,
    newPassword,
    otp,
  }: {
    email: string
    newPassword: string
    otp: string
  }): Promise<void> {
    const res = await request<ApiResponse<null>>(this.#lumi, '/lm/user/password/reset', {
      method: 'POST',
      body: {
        projectId: this.#lumi.config.projectId,
        email,
        newPassword: SHA256(newPassword).toString(),
        code: otp,
      },
    })

    if (res.code !== 200)
      throw new LumiError(res.code, res.message)
  }

  /** 第三方登录 */
  public signInWithOAuth({
    provider,
  }: {
    provider: OAuthProvider
  }): Promise<MessageSignInData> {
    return this.#openAuthPopup(`${this.#lumi.config.authOrigin}/oauth/${provider}`)
  }

  /** 退出登录 */
  public signOut(): void {
    if (isServer)
      throw new Error('auth.signOut() can only be called on the client side')

    this.accessToken = null
    this.user = null
  }

  /** 获取当前用户 */
  public async refreshUser(): Promise<User> {
    const res = await request<ApiResponse<User>>(this.#lumi, '/lm/user/info', {
      method: 'POST',
    })
    if (res.code !== 200)
      throw new Error(res.message)
    this.user = res.data
    return res.data
  }

  /** 监听登录状态变化 */
  public onAuthChange(callback: (args: {
    isAuthenticated: boolean
    user: User | null
  }) => void): () => void {
    if (isServer)
      throw new Error('auth.onAuthChange() can only be called on the client side')

    const unlisten = this.#lumi.config.storageAdapter.listen((key): void => {
      if (key === StorageKey.ACCESS_TOKEN || key === StorageKey.USER || !key) {
        callback({
          isAuthenticated: this.isAuthenticated,
          user: this.user,
        })
      }
    })

    return () => unlisten()
  }

  /** 打开认证弹窗并处理消息 */
  #openAuthPopup(url: string): Promise<MessageSignInData> {
    if (isServer)
      throw new LumiError(10400, 'This method can only be called on the client side')

    const width = 800
    const height = 600
    const left = (window.screen.width - width) / 2
    const top = (window.screen.height - height) / 2
    const popup = window.open(url, this.#popupName, `width=${width},height=${height},left=${left},top=${top}`)

    let cleanup: () => void
    return new Promise<MessageSignInData>((resolve, reject) => {
      if (!popup)
        return reject(new LumiError(10500, 'Open auth window failed'))

      const timer = setInterval(() => {
        if (popup.closed)
          reject(new LumiError(10499, 'Auth window closed'))
      }, 1000)

      const handleGlobalClick = (event: MouseEvent): void => {
        if (!popup.closed) {
          popup.focus()
          event.stopPropagation()
          event.preventDefault()
        }
      }

      const handleMessage = ({ data, origin, source }: MessageEvent<MessageDataReceive | null>): void => {
        if (origin !== this.#lumi.config.authOrigin || source !== popup)
          return

        switch (data?.type) {
          case ReceiveMessageType.READY: {
            popup.postMessage({
              type: SendMessageType.INIT,
              data: {
                projectId: this.#lumi.config.projectId,
                icon: getIcon(),
                title: getTitle(),
              },
            } satisfies MessageDataSend, this.#lumi.config.authOrigin)
            break
          }
          case ReceiveMessageType.SIGN_IN: {
            if (data.data.projectId !== this.#lumi.config.projectId)
              break
            popup.close()
            window.focus()
            this.accessToken = data.data.accessToken
            this.user = data.data.user
            resolve(data.data)
            break
          }
        }
      }

      window.addEventListener('message', handleMessage)
      document.addEventListener('click', handleGlobalClick, true)

      cleanup = () => {
        clearInterval(timer)
        window.removeEventListener('message', handleMessage)
        document.removeEventListener('click', handleGlobalClick, true)
      }
    }).finally(() => cleanup?.())
  }
}
