import type { LumiClientConfig } from '@/types'
import type { Optional } from '@/types/utils'
import { createDefaultStorageAdapter } from '@/adapters/storage'
import { LumiAuthClient } from '@/core/auth-client'
import { EntitiesClient } from '@/core/entities-client'
import { FunctionsClient } from '@/core/functions-client'
import { ToolsClient } from '@/core/tools-client'

export class LumiClient {
  public config: LumiClientConfig

  public auth: LumiAuthClient
  public entities: EntitiesClient
  public tools: ToolsClient
  public functions: FunctionsClient

  constructor(config: Optional<LumiClientConfig, 'storageAdapter'>) {
    config.storageAdapter ??= createDefaultStorageAdapter()

    this.config = config as LumiClientConfig
    this.auth = new LumiAuthClient(this)
    this.entities = new EntitiesClient(this)
    this.tools = new ToolsClient(this)
    this.functions = new FunctionsClient(this)
  }
}

export function createClient(config: Optional<LumiClientConfig, 'storageAdapter'>): LumiClient {
  return new LumiClient(config)
}
